97	static void * _buf_malloc(size_t size_bytes, lv_color_format_t cf)
98	{
99	    uint8_t align_bytes = VGLITE_BUF_ALIGNMENT;
100	
101	    /*Allocate larger memory to be sure it can be aligned as needed*/
102	    size_bytes += align_bytes - 1;
103	
104	    return lv_malloc(size_bytes);
105	}
