107	static void * _buf_align(void * buf, lv_color_format_t cf)
108	{
109	    uint8_t align_bytes = VGLITE_BUF_ALIGNMENT;
110	
111	    uint8_t * buf_u8 = buf;
112	    if(buf_u8) {
113	        buf_u8 += align_bytes - 1;
114	        buf_u8 = (uint8_t *)((lv_uintptr_t)buf_u8 & ~(align_bytes - 1));
115	    }
116	
117	    return buf_u8;
118	}
