static inline void safe_obj_hide_and_null(lv_obj_t **obj_ptr)
{
    if (*obj_ptr != NULL)
    {
        printf("[xiaozhi] safe_obj_hide_and_null: hiding obj=%p\n", (void*)*obj_ptr);
