input.new_string:
  /* Speak button: 根据状态切换图片和可见性
   *
   * CRITICAL: lv_image_set_src 对 LV_IMAGE_SRC_FILE 即使是同一个 src 也会
   * lv_strdup 新路径副本 + lv_free 旧副本 + lv_obj_invalidate + 重新解码图片
   * （图片缓存禁用，每次渲染都 draw_buf_create 分配 / decoder_close 释放 draw buf）。
   * ui_refresh 每 100ms 调用一次，若每次都重复 set_src 同一张图，会让 LVGL
   * TLSF 堆在反复 malloc/free 中被破坏 → 退出后渲染触发 MMFAR=0x15c 崩溃。
   * 因此只在目标图片变化时才 set_src，避免每 100ms 重复 strdup/free + 重新解码。 */
  if (app->speak_btn != NULL)
    {
      bool live = app->handshake_done && !app->ws_dead && !app->dialog_running;

      /* 识别中和识别成功状态：隐藏voice图标，显示动画 */
      if (app->state == XZ_STATE_THINKING || app->state == XZ_STATE_PLAYING)
        {
          if (s_speak_btn_visible)
            {
              lv_obj_add_flag(app->speak_btn, LV_OBJ_FLAG_HIDDEN);
              s_speak_btn_visible = false;
            }
        }
      else
        {
          /* 其他状态：显示voice图标 */
          if (!s_speak_btn_visible)
            {
              lv_obj_clear_flag(app->speak_btn, LV_OBJ_FLAG_HIDDEN);
              s_speak_btn_visible = true;
            }

          /* 选择本帧应显示的图标，仅当与上次不同时才 set_src */
          const char *want_icon;
          if (live || app->state == XZ_STATE_READY)
            {
              want_icon = (app->state == XZ_STATE_LISTENING)
                            ? VOICE_BTN_LISTENING : VOICE_BTN_READY;
            }
          else
            {
              /* 连接中或错误状态 */
              want_icon = VOICE_BTN_CONNECTING;
            }

          if (s_speak_btn_icon != want_icon)
            {
              lv_image_set_src(app->speak_btn, want_icon);
              s_speak_btn_icon = want_icon;
            }
        }
    }
}

