280	/**
281	 * Open a PNG image and decode it into dsc.decoded
282	 * @param decoder   pointer to the decoder where this function belongs
283	 * @param dsc       decoded image descriptor
284	 * @return          LV_RESULT_OK: no error; LV_RESULT_INVALID: can't open the image
285	 */
286	static lv_result_t decoder_open(lv_image_decoder_t * decoder, lv_image_decoder_dsc_t * dsc)
287	{
288	    LV_UNUSED(decoder);
289	
290	    const uint8_t * png_data = NULL;
291	    size_t png_data_size = 0;
292	    if(dsc->src_type == LV_IMAGE_SRC_FILE) {
293	        const char * fn = dsc->src;
294	        if(lv_strcmp(lv_fs_get_ext(fn), "png") == 0) {              /*Check the extension*/
295	            unsigned error;
296	            error = lodepng_load_file((void *)&png_data, &png_data_size, fn);  /*Load the file*/
297	            if(error) {
298	                if(png_data != NULL) {
299	                    lv_free((void *)png_data);
300	                }
301	                LV_LOG_WARN("error %u: %s\n", error, lodepng_error_text(error));
302	                return LV_RESULT_INVALID;
303	            }
304	        }
305	    }
306	    else if(dsc->src_type == LV_IMAGE_SRC_VARIABLE) {
307	        const lv_image_dsc_t * img_dsc = dsc->src;
308	        png_data = img_dsc->data;
309	        png_data_size = img_dsc->data_size;
310	    }
311	    else {
312	        return LV_RESULT_INVALID;
313	    }
314	
315	    lv_draw_buf_t * decoded = decode_png_data(png_data, png_data_size);
316	
317	    if(dsc->src_type == LV_IMAGE_SRC_FILE) lv_free((void *)png_data);
318	
319	    if(!decoded) {
320	        LV_LOG_WARN("Error decoding PNG");
321	        return LV_RESULT_INVALID;
322	    }
323	
324	    lv_draw_buf_t * adjusted = lv_image_decoder_post_process(dsc, decoded);
325	    if(adjusted == NULL) {
326	        draw_buf_destroy(decoded);
327	        return LV_RESULT_INVALID;
328	    }
329	
330	    /*The adjusted draw buffer is newly allocated.*/
331	    if(adjusted != decoded) {
332	        draw_buf_destroy(decoded);
333	        decoded = adjusted;
334	    }
335	
336	    dsc->decoded = decoded;
337	
338	    if(dsc->args.no_cache) return LV_RESULT_OK;
339	
340	#if ((LVGL_VERSION_MAJOR >= 9) && (LVGL_VERSION_MINOR >= 2)) || defined(NUTTX_LVGL)
341	    /*If the image cache is disabled, just return the decoded image*/
342	    if(!lv_image_cache_is_enabled()) return LV_RESULT_OK;
343	
344	    /*Add the decoded image to the cache*/
345	    lv_image_cache_data_t search_key;
346	    search_key.src_type = dsc->src_type;
347	    search_key.src = dsc->src;
348	    search_key.slot.size = decoded->data_size;
349	
350	    lv_cache_entry_t * entry = lv_image_decoder_add_to_cache(decoder, &search_key, decoded, NULL);
351	
352	    if(entry == NULL) {
353	        return LV_RESULT_INVALID;
354	    }
355	    dsc->cache_entry = entry;
356	
357	#elif LV_CACHE_DEF_SIZE > 0
358	    /*Add the decoded image to the cache*/
359	    lv_image_cache_data_t search_key;
360	    search_key.src_type = dsc->src_type;
361	    search_key.src = dsc->src;
362	    search_key.slot.size = decoded->data_size;
363	
364	    lv_cache_entry_t * entry = lv_image_decoder_add_to_cache(decoder, &search_key, decoded, NULL);
365	
366	    if(entry == NULL) {
367	        return LV_RESULT_INVALID;
368	    }
369	    dsc->cache_entry = entry;
370	#endif
371	
372	    return LV_RESULT_OK;    /*If not returned earlier then it failed*/
373	}
