396	/************************** PNG Hardware decode *******************************/
397	#ifdef PNG_HW_DECODE
398	static int bespng_get_info(uint8_t *png_data, uint32_t png_size, int *width, int *height)
399	{
400	    int comp_level = 0;
401	    const uint8_t png_hdr[] = {0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a};
402	    uint8_t *data = png_data;
403	    uint8_t *p;
404	
405	    for (int i = 0; i < sizeof(png_hdr); i++) {
406	        if (data[i] != png_hdr[i])
407	            return -1;
408	    }
409	
410	#define PNG_GET32(p, n)  ((p[n] << 24) | (p[n + 1] << 16) | (p[n + 2] << 8) | p[n + 3])
411	
412	    p = data + 8;
413	    while (p - data < png_size) {
414	        uint32_t chunk_len = PNG_GET32(p, 0);
415	        if (p[4] == 'I' && p[5] == 'H' && p[6] == 'D' && p[7] == 'R') {
416	            /* IHDR, parse image info */
417	            *width = PNG_GET32(p, 8);
418	            *height = PNG_GET32(p, 12);
419	        } else if (p[4] == 'I' && p[5] == 'D' && p[6] == 'A' && p[7] == 'T') {
420	            /* IDAT, get zlib compress level */
421	            if (p[8] == 0x78 && p[9] == 0x01) {
422	                if (p[10] & 0x4)
423	                    comp_level = 1;
424	                else
425	                    comp_level = 0;
426	            } else if (p[8] == 0x78 && p[9] == 0x5E) {
427	                comp_level = 1;
428	            } else if (p[8] == 0x78 && p[9] == 0x9C) {
429	                comp_level = 2;
430	            } else if (p[8] == 0x78 && p[9] == 0xDA) {
431	                comp_level = 3;
432	            } else {
433	                comp_level = 0xff;
434	            }
435	            break;
436	        }
437	        p += 12 + chunk_len;
438	    }
439	    LV_LOG_TRACE("PNG image %dx%d, compress level %d", *width, *height, comp_level);
440	    return (comp_level > 0) ? -1 : 0;
441	}
