443	static lv_draw_buf_t * decode_png_data(const void * png_data, size_t png_data_size)
444	{
445	    struct HAL_PNG_CONFIG_T cfg;
446	    int timeout = 0;
447	    int w = 0, h = 0;
448	    lv_draw_buf_t *draw_buf = NULL;
449	    int i;
450	
451	    if (png_data == NULL || png_data_size <= 0) {
452	        LV_LOG_ERROR("png data is NULL.");
453	        return NULL;
454	    }
455	
456	    LV_LOG_TRACE("PNG data %p, size %d bytes", png_data, png_data_size);
457	
458	    if (bespng_get_info((uint8_t *)png_data, 1024, &w, &h) != 0) {
459	        LV_LOG_ERROR("Invalid png data.");
460	        return NULL;
461	    }
462	    if (w <= 0 || h <= 0) {
463	        LV_LOG_ERROR("Invalid png size, %dx%d", w, h);
464	        return NULL;
465	    }
466	
467	    draw_buf = draw_buf_create(w, h, LV_COLOR_FORMAT_ARGB8888, w * 4);
468	    if (draw_buf == NULL) {
469	        LV_LOG_ERROR("Can't malloc draw_buf.");
470	        return NULL;
471	    }
472	
473	    if (draw_buf->data_size < w * h * 4) {
474	        LV_LOG_ERROR("Small draw_buf %u < %dx%dx4", draw_buf->data_size, w, h);
475	        draw_buf_destroy(draw_buf);
476	        return NULL;
477	    }
478	
479	    hal_cache_sync(HAL_CACHE_ID_D_CACHE, ADDR_ALIGN_TO_CACHE((uint32_t)png_data),
480	            LEN_ALIGN_TO_CACHE(png_data_size, (uint32_t)png_data));
481	    hal_cache_invalidate(HAL_CACHE_ID_D_CACHE, ADDR_ALIGN_TO_CACHE((uint32_t)draw_buf->data),
482	            LEN_ALIGN_TO_CACHE((uint32_t)draw_buf->data_size, (uint32_t)draw_buf->data));
483	
484	    hal_png_open();
485	
486	    lv_memset(&cfg, 0, sizeof(cfg));
487	    cfg.png_data = (uint8_t *)png_data;
488	    cfg.png_size = png_data_size;
489	    cfg.pix_buf = draw_buf->data;
490	    cfg.pix_fmt = HAL_PNG_PIX_RGBA8888;
491	
492	    if (hal_png_start(&cfg) != HAL_PNG_OK) {
493	        LV_LOG_ERROR("Decode start failed. %d", cfg.result);
494	        goto error;
495	    }
496	
497	    for (i = 0; i < TIMEOUT_MS; i++) {
498	        if (!hal_png_busy())
499	            break;
500	        lv_delay_ms(1);
501	    }
502	    if (i >= TIMEOUT_MS)
503	        timeout = 1;
504	
505	    if (timeout) {
506	        LV_LOG_ERROR("PNG decode timeout!");
507	        goto error;
508	    } else if (cfg.result != HAL_PNG_OK) {
509	        LV_LOG_ERROR("PNG decode failed, result = %d.", cfg.result);
510	        goto error;
511	    }
512	
513	    LV_LOG_TRACE("PNG decode done, %dx%d", cfg.img_width, cfg.img_height);
514	    return draw_buf;
515	
516	error:
517	    hal_png_stop();
518	    hal_png_close();
519	    draw_buf_destroy(draw_buf);
520	    return NULL;
521	}
