134	void lv_image_set_src(lv_obj_t * obj, const void * src)
135	{
136	    LV_LOG_ERROR("---sunbin--- lv_image_set_src src=%s", (const char *)src);
137	    LV_ASSERT_OBJ(obj, MY_CLASS);
138	
139	    lv_obj_invalidate(obj);
140	
141	    lv_image_src_t src_type = lv_image_src_get_type(src);
142	    LV_LOG_ERROR("---sunbin--- lv_image_set_src src=%p, src_type=%d", src, src_type);
143	    lv_image_t * img = (lv_image_t *)obj;
144	
145	#if LV_USE_LOG && LV_LOG_LEVEL <= LV_LOG_LEVEL_INFO
146	    switch(src_type) {
147	        case LV_IMAGE_SRC_FILE:
148	            LV_LOG_TRACE("`LV_IMAGE_SRC_FILE` type found");
149	            break;
150	        case LV_IMAGE_SRC_VARIABLE:
151	            LV_LOG_TRACE("`LV_IMAGE_SRC_VARIABLE` type found");
152	            break;
153	        case LV_IMAGE_SRC_SYMBOL:
154	            LV_LOG_TRACE("`LV_IMAGE_SRC_SYMBOL` type found");
155	            break;
156	        default:
157	            LV_LOG_WARN("unknown type");
158	    }
159	#endif
160	
161	    /*If the new source type is unknown free the memories of the old source*/
162	    if(src_type == LV_IMAGE_SRC_UNKNOWN) {
163	        LV_LOG_WARN("unknown image type");
164	        if(img->src_type == LV_IMAGE_SRC_SYMBOL || img->src_type == LV_IMAGE_SRC_FILE) {
165	            lv_free((void *)img->src);
166	        }
167	        img->src      = NULL;
168	        img->src_type = LV_IMAGE_SRC_UNKNOWN;
169	        return;
170	    }
171	
172	    lv_image_header_t header;
173	    lv_result_t res = lv_image_decoder_get_info(src, &header);
174	    if(res != LV_RESULT_OK) {
175	#if LV_USE_LOG
176	        char buf[24];
177	        LV_LOG_WARN("failed to get image info: %s",
178	                    src_type == LV_IMAGE_SRC_FILE ? (const char *)src : (lv_snprintf(buf, sizeof(buf), "%p", src), buf));
179	#endif /*LV_USE_LOG*/
180	        return;
181	    }
182	
183	    /*Save the source*/
184	    if(src_type == LV_IMAGE_SRC_VARIABLE) {
185	        /*If memory was allocated because of the previous `src_type` then free it*/
186	        if(img->src_type == LV_IMAGE_SRC_FILE || img->src_type == LV_IMAGE_SRC_SYMBOL) {
187	            lv_free((void *)img->src);
188	        }
189	        img->src = src;
190	    }
191	    else if(src_type == LV_IMAGE_SRC_FILE || src_type == LV_IMAGE_SRC_SYMBOL) {
192	        /*If the new and the old src are the same then it was only a refresh.*/
193	        if(img->src != src) {
194	            const void * old_src = NULL;
195	            /*If memory was allocated because of the previous `src_type` then save its pointer and free after allocation.
196	             *It's important to allocate first to be sure the new data will be on a new address.
197	             *Else `img_cache` wouldn't see the change in source.*/
198	            if(img->src_type == LV_IMAGE_SRC_FILE || img->src_type == LV_IMAGE_SRC_SYMBOL) {
199	                old_src = img->src;
200	            }
201	#if LV_USE_FS_MEMFS
202	            /* is memfs file? */
203	            if (lv_strlen(src) <= 7 && ((char *)src)[0] == LV_FS_MEMFS_LETTER && ((char *)src)[1] == ':') {
204	                lv_fs_path_ex_t *new_path = (lv_fs_path_ex_t *)lv_malloc(sizeof(lv_fs_path_ex_t));
205	                if(new_path == NULL) return;
206	                lv_memcpy(new_path, src, sizeof(lv_fs_path_ex_t));
207	                img->src = (void *)new_path;
208	            } else
209	#endif
210	            {
211	                char * new_str = lv_strdup(src);
212	                LV_ASSERT_MALLOC(new_str);
213	                if(new_str == NULL) return;
214	                img->src = new_str;
215	            }
216	
217	            if(old_src) lv_free((void *)old_src);
218	        }
219	    }
220	
221	    if(src_type == LV_IMAGE_SRC_SYMBOL) {
222	        /*`lv_image_dsc_get_info` couldn't set the width and height of a font so set it here*/
223	        const lv_font_t * font = lv_obj_get_style_text_font(obj, LV_PART_MAIN);
224	        int32_t letter_space = lv_obj_get_style_text_letter_space(obj, LV_PART_MAIN);
225	        int32_t line_space = lv_obj_get_style_text_line_space(obj, LV_PART_MAIN);
226	        lv_point_t size;
227	        lv_text_get_size(&size, src, font, letter_space, line_space, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
228	        header.w = size.x;
229	        header.h = size.y;
230	    }
231	
232	    img->src_type = src_type;
233	    img->w        = header.w;
234	    img->h        = header.h;
235	    img->cf       = header.cf;
236	    LV_LOG_INFO("---sunbin--- lv_image_set_src img->w=%d, img->h=%d, img->cf=%d", img->w, img->h, img->cf);
237	    lv_obj_refresh_self_size(obj);
238	
239	    update_align(obj);
240	
241	    /*Provide enough room for the rotated corners*/
242	    if(img->rotation || img->scale_x != LV_SCALE_NONE || img->scale_y != LV_SCALE_NONE) {
243	        lv_obj_refresh_ext_draw_size(obj);
244	    }
245	
246	    lv_obj_invalidate(obj);
247	}
