162	/* MCP tool: send_json wrapper (app context via static pointer).
163	 * Wraps the JSON-RPC response in the xiaozhi transport format:
164	 * {"type":"mcp","payload":{...}}
165	 */
166	
167	static int mcp_send_json(cJSON *msg)
168	{
169	  if (s_mcp_app == NULL)
170	    {
171	      return -1;
172	    }
173	
174	  /* Wrap in transport format: {"type":"mcp","payload":<original>} */
175	
176	  cJSON *wrapper = cJSON_CreateObject();
177	  cJSON_AddStringToObject(wrapper, "type", "mcp");
178	  cJSON *payload = cJSON_Duplicate(msg, 1);
179	  cJSON_AddItemToObject(wrapper, "payload", payload);
180	
181	  int ret = send_json(s_mcp_app, wrapper);
182	  cJSON_Delete(wrapper);
183	  return ret;
184	}
