749	
750	    /* 外圈反向旋转 ~3s/圈, 每次转10度 */
751	    if (s_orbit_outer != NULL)
752	    {
753	        int32_t angle = 360 - ((s_orbit_tick * 10) % 360);
754	        lv_arc_set_rotation(s_orbit_outer, angle);
